import sys
IW, IH = 1280, 720

with open(sys.argv[1], "rb") as f:
    D = f.read()


def solve(A, b):
    n = len(A)
    M = [row[:] + [b[i]] for i, row in enumerate(A)]
    for c in range(n):
        p = max(range(c, n), key=lambda r: abs(M[r][c]))
        M[c], M[p] = M[p], M[c]
        piv = M[c][c]
        for j in range(c, n + 1):
            M[c][j] /= piv
        for r in range(n):
            if r != c and M[r][c]:
                fr = M[r][c]
                for j in range(c, n + 1):
                    M[r][j] -= fr * M[c][j]
    return [M[i][n] for i in range(n)]


def compute_H(corn):
    A = []
    b = []
    for (u, v), (x, y) in corn.items():
        A.append([u, v, 1, 0, 0, 0, -u * x, -v * x]); b.append(x)
        A.append([0, 0, 0, u, v, 1, -u * y, -v * y]); b.append(y)
    h = solve(A, b); h.append(1.0)
    return h


def apply_H(H, u, v):
    x = H[0] * u + H[1] * v + H[2]
    y = H[3] * u + H[4] * v + H[5]
    w = H[6] * u + H[7] * v + H[8]
    return x / w, y / w


def brightness_grid(corn):
    H = compute_H(corn)
    g = []
    for v in range(8):
        for u in range(8):
            cx, cy = apply_H(H, u + 0.5, v + 0.5)
            s = 0; n = 0
            for dx in range(-2, 3):
                for dy in range(-2, 3):
                    x = int(round(cx + dx)); y = int(round(cy + dy))
                    if 0 <= x < IW and 0 <= y < IH:
                        s += D[y * IW + x]; n += 1
            g.append(s / n if n else 0)
    return g


def score(corn):
    g = brightness_grid(corn)
    p0 = [g[v * 8 + u] for v in range(8) for u in range(8) if (u + v) % 2 == 0]
    p1 = [g[v * 8 + u] for v in range(8) for u in range(8) if (u + v) % 2 == 1]
    p0.sort(); p1.sort()
    # use medians to be robust to the few pieces
    m0 = p0[len(p0) // 2]; m1 = p1[len(p1) // 2]
    return abs(m0 - m1)


# start corners
corn = {(0, 0): [494.0, 411.0], (8, 0): [829.0, 362.0],
        (0, 8): [462.0, 627.0], (8, 8): [952.0, 546.0]}


def to_tuplekeys(c):
    return {k: (v[0], v[1]) for k, v in c.items()}


best = score(to_tuplekeys(corn))
keys = [(0, 0), (8, 0), (0, 8), (8, 8)]
step = 8.0
for it in range(400):
    improved = False
    for k in keys:
        for axis in (0, 1):
            for d in (step, -step):
                cand = {kk: vv[:] for kk, vv in corn.items()}
                cand[k][axis] += d
                sc = score(to_tuplekeys(cand))
                if sc > best + 1e-6:
                    best = sc; corn = cand; improved = True
    if not improved:
        step /= 2
        if step < 0.5:
            break

print("best score", round(best, 2), "step", step)
print("corners:")
for k in keys:
    print(k, round(corn[k][0], 1), round(corn[k][1], 1))
# print grid
g = brightness_grid(to_tuplekeys(corn))
print("brightness grid:")
for v in range(8):
    print("v%d " % v + " ".join("%3.0f" % g[v * 8 + u] for u in range(8)))

